\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{booktabs}

\title{Graph Neural Networks for Band Gap Prediction in Perovskite Oxides}
\author{S.~Reyes and T.~Aldana}
\date{}

\begin{document}
\maketitle

\section{Model and Training Details}
We represent each candidate perovskite oxide as a crystal graph and train
a message-passing neural network to predict its band gap. All models are
trained with the AdamW optimizer. We use a batch size of 128 structures
and a peak learning rate of $3\times10^{-4}$. The learning rate follows a
linear warmup schedule for the first 2000 optimization steps, after which
it decays cosinely to zero over the remaining 48000 steps. Training runs
for 50 epochs on a single accelerator and takes roughly six hours.

\subsection{Hyperparameter Selection}
\begin{table}[h]
\centering
\begin{tabular}{ll}
\toprule
Hyperparameter & Value \\
\midrule
Batch size & 128 \\
Peak learning rate & $3\times10^{-4}$ \\
Warmup steps & 2000 \\
Total steps & 50000 \\
Weight decay & 0.01 \\
\bottomrule
\end{tabular}
\caption{Training hyperparameters used for all reported models.}
\label{tab:hyp}
\end{table}

The warmup phase is followed by cosine decay, which we found to give more
stable convergence than a constant schedule across three random seeds.

\end{document}
